document.addEventListener("DOMContentLoaded",()=>{const e=window.matchMedia("(prefers-reduced-motion: reduce)").matches,t=document.querySelectorAll(".home-hero__slide");if(t.length>1&&!e){let e=0;window.setInterval(()=>{t[e].classList.remove("is-active"),e=(e+1)%t.length,t[e].classList.add("is-active")},5e3)}const o=document.querySelector(".home-hero__typed");if(!o)return;const n=(o.dataset.words||"").split(",").map(e=>e.trim()).filter(Boolean);if(0===n.length)return;if(e)return;let i=0,d=0,s=!1;o.textContent="";const r=()=>{const e=n[i];return s?(d-=1,o.textContent=e.slice(0,d),0===d?(s=!1,i=(i+1)%n.length,void window.setTimeout(r,200)):void window.setTimeout(r,200)):(d+=1,o.textContent=e.slice(0,d),d===e.length?(s=!0,void window.setTimeout(r,600)):void window.setTimeout(r,200))};window.setTimeout(r,75)});